<?php
require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../includes/auth.php';require_login();
$rows=$conn->query("SELECT s.*,c.car_name,c.plate_number,d.name dalali_name,IFNULL(p.paid,0) paid FROM car_sales s JOIN cars c ON c.id=s.car_id LEFT JOIN dalalis d ON d.id=s.dalali_id LEFT JOIN(SELECT sale_id,SUM(amount) paid FROM sale_payments GROUP BY sale_id)p ON p.sale_id=s.id ORDER BY s.sale_date DESC,s.id DESC");
$page_title='Sales';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';?>
<div class="content-page"><div class="report-title"><div><h1 class="page-title">Sales Register</h1><p class="muted">Completed sales, customer balances, payment collection and receipts.</p></div></div><div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Car</th><th>Buyer</th><th>Sale Price</th><th>Paid</th><th>Balance</th><th>Payment Status</th><th>Dalali</th><th>Actions</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):$bal=max(0,(float)$r['sale_price']-(float)$r['paid']);?><tr><td><?=e($r['sale_date'])?></td><td><?=e($r['car_name'].' / '.car_sales_plate_label($r['plate_number']))?></td><td><?=e($r['buyer_name'])?></td><td><?=money($r['sale_price'])?></td><td><?=money($r['paid'])?></td><td><?=money($bal)?></td><td><span class="badge <?=$r['payment_status']==='PAID'?'sold':($r['payment_status']==='PARTIAL'?'stock':'loss')?>"><?=e($r['payment_status'])?></span></td><td><?=e($r['dalali_name']?:'Direct sale')?></td><td><a class="btn" href="receipt.php?id=<?=$r['id']?>">Receipt</a> <a class="btn" href="agreement.php?id=<?=$r['id']?>">Agreement</a><?php if($bal>0):?> <a class="btn btn-green" href="payment.php?id=<?=$r['id']?>">Add Payment</a><?php endif;?><?php if(is_admin()):?> <a class="btn btn-red" href="void.php?id=<?=$r['id']?>">Void</a><?php endif;?></td></tr><?php endwhile;?></tbody></table></div></div></div><?php include __DIR__.'/../includes/footer.php';?>
